-- Stage 5 Unit 1 import foundation.
-- Imported questions remain inactive until the final activation migration.

begin;

insert into storage.buckets (id, name, public)
values ('question-imports', 'question-imports', true)
on conflict (id) do update
set public = true;

with
topic_payload as (
  select $unit1_json$[{"slug": "digital-data", "title": "Digital data", "is_enabled": false, "display_order": 1}, {"slug": "software", "title": "Software", "is_enabled": false, "display_order": 2}, {"slug": "database-applications", "title": "Database applications", "is_enabled": false, "display_order": 3}, {"slug": "spreadsheet-applications", "title": "Spreadsheet applications", "is_enabled": false, "display_order": 4}, {"slug": "computer-hardware", "title": "Computer hardware", "is_enabled": false, "display_order": 5}, {"slug": "network-technologies", "title": "Network technologies", "is_enabled": false, "display_order": 6}, {"slug": "cyberspace-network-security-and-data-transfer", "title": "Cyberspace, network security and data transfer", "is_enabled": false, "display_order": 7}, {"slug": "cloud-technology", "title": "Cloud technology", "is_enabled": false, "display_order": 8}, {"slug": "ethical-legal-and-environmental-impact", "title": "Ethical, legal and environmental impact", "is_enabled": false, "display_order": 9}, {"slug": "changes-in-employment-opportunities-skills-requirements-and-work-practices", "title": "Changes in employment opportunities, skills requirements and work practices", "is_enabled": false, "display_order": 10}, {"slug": "health-and-safety", "title": "Health and safety", "is_enabled": false, "display_order": 11}, {"slug": "digital-applications", "title": "Digital applications", "is_enabled": false, "display_order": 12}]$unit1_json$::jsonb as data
),
topic_rows as (
  select *
  from topic_payload,
  jsonb_to_recordset(topic_payload.data) as row(
    slug text,
    title text,
    is_enabled boolean,
    display_order integer
  )
)
insert into public.topics (slug, title, is_enabled, display_order)
select slug, title, is_enabled, display_order
from topic_rows
on conflict (slug) do update
set title = excluded.title,
    display_order = excluded.display_order;

